type Point = { x: number; y: number };
type Named = { name: string };

type NamedPoint = Point & Named;

const entity: NamedPoint = {
  x: 1,
  y: 2,
  name: "origin",
  id: "p-1", // extra field on wider object
};

const asPoint: Point = entity; // OK — structural match

type User = { id: string; name: string };

function saveUser(user: User): void {
  console.log(user.id);
}

// Error: 'email' does not exist in type 'User'
// saveUser({ id: "1", name: "Ada", email: "a@b.c" });

const draft = { id: "1", name: "Ada", email: "a@b.c" };
saveUser(draft); // OK — draft is not a fresh literal at call site

type Status = "pending" | "done";

let narrow: "pending" = "pending";
let wide: Status = narrow;    // OK — literal fits union

// narrow = wide;            // Error — wide might be "done"

function onlyPending(s: "pending") {}
// onlyPending(wide);         // Error

type Mutable = { items: string[] };
type Immutable = { readonly items: readonly string[] };

const imm: Immutable = { items: ["a"] };
// const mut: Mutable = imm; // Error: readonly array not assignable to mutable

const mut: Mutable = { items: ["a"] };
const imm2: Immutable = mut; // OK — mutable is assignable to readonly
